public static function setMouseCursorIcon(icon:CodeCursor):Void
	{
		final valid:Bool = external.ExternalMac.setCursorIcon(icon.toInt(), null, 0, 0);

		if (!valid)
			Mouse.cursor = icon.toOpenFL();
